+/** Picks a supported language (`en` or `ko`) from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  let bestLang = null;
+  let bestQ = 0;
+  for (const part of raw.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    const tag = rawTag.trim();
+    if (!/^[a-z]{2,3}(?:-[a-z0-9]{1,8})*$/i.test(tag)) continue;
+    const primary = tag.split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(primary)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const [k, v] = p.split("=").map((s) => s.trim());
+      if (k === "q" || k === "Q") {
+        q = v === "" ? NaN : Number(v);
+        if (!Number.isFinite(q) || q < 0 || q > 1) valid = false;
+      } else {
+        valid = false;
+      }
+    }
+    if (!valid || q <= 0) continue;
+    if (q > bestQ) {
+      bestQ = q;
+      bestLang = primary;
+    }
+  }
+  return bestLang ?? fallback;
+}
